// config_dictionary.dart
//
// FALLBACK descriptions for the (i) info buttons: used only when a config
// key has no entry in ui_schema.json. That file is where descriptions are
// maintained (and where the newer keys live) - the text below mirrors it,
// so a description changed there should be changed here too, or the key
// dropped from this map and left to the schema.
class ConfigDictionary {
  static const Map<String, String> descriptions = {
    "btn_name": "GUI object name for the connection status that has two states. Usually represented as a red dot when disconnected.",
    "com_type": "Type of connection as a string. 'Serial' opens a COM port on the host processor/spdevice (the only one that reads serial_port and baud); 'SerialOverEthernet' and 'Network' both reach the device by ip_address + net_port; 'HTTP' posts to it over ip_address + net_port with the user/password credentials.",
    "host": "The processor or spdevice in use for serial connections.",
    "relay_host": "The processor in use for the relay power control.",
    "device_id": "The ID to be sent to the device if it is required.",
    "gve_id": "String that identifies the device in GVE. Needs to be created when you add the room devices to GVE.",
    "input": "Input for the device. The subscribe status will change to this input. (Examples: HDBaseT, HDMI 1, Digital Link).",
    "ip_address": "IP address for the device as a string. Network, SerialOverEthernet and HTTP all reach the device through it; a Serial device is wired to a COM port on its host instead and does not carry the key.",
    "keep_alive_command": "Command as a string to send to the device once connected. Chosen from the dictionary of commands in the module.",
    "keep_alive_interval": "Timing for sending the keep_alive_command as an integer.",
    "keep_alive_qualifier": "Only needed if the command requires a qualifier (Example checking an audio group such as '1' as the qualifier).",
    "lbl_name": "Name for the GUI object that will be written for connection status.",
    "manual_disconnect": "Flag to disconnect the item. Used if a projector or item is temporarily removed from a room.",
    "model": "Model of the device. Picking a model from the dropdown switches 'module' to that model's default python file and applies the module's DEVICE_INFO connection + standard defaults (protocol, port, keep-alive, input, ...). The list is built from each module's DEVICE_INFO \"models\" list (falling back to its self.Models keys) and is filtered to this tab's device family via DEVICE_INFO \"device_type\"; the browse dialog can show all types.",
    "keep_alive_trigger": "Delay the keep_alive_command until the trigger is received such as the APC needing to complete the login before polling.",
    "default_cc_aud_cam": "In a two-camera room, start with the AUDIENCE camera selected as the capture-card source instead of the instructor camera — what the far end of a call sees when the room comes up. Ignored in a room with fewer than two cameras.",
    "gui_capture_source_available": "Whether the panel offers a capture-source page at all — the controls that pick what gets sent to the capture card / USB interface for a Zoom or Teams call. 'No' hides them, for a room whose capture feed is fixed or that has no capture card.",
    "gui_usb_or_vga": "Set the GUI and metrics to send over the USB or VGA depending on the age of the room.",
    "ntp_primary": "Network Time Protocol (NTP) primary server address in use for the processor.",
    "ntp_secondary": "Network Time Protocol (NTP) secondary server address in use for the processor.",
    "output_audio_ald": "Switcher output feeding the Assisted Listening system. It gets the same audio tie as output_audio on every source change and at startup, so the ALD hears whatever the room hears. Blank in a room without one. Non-digits are stripped, so '4A' reaches the switcher as 4.",
    "gui_demo_mode": "Bring the room up with every device faked: each one gets a dummy connection handler, so the panel is fully usable while nothing is actually talked to. For demonstrating or exercising a panel off the hardware. Leave it false in a live room — no command reaches a device while it is on.",
    "module": "File path to the module as a string.",
    "name": "Name of the device as it will appear in the logger.",
    "net_port": "Network Port used to send communications on network connected devices. Not carried by a Serial device, which talks over serial_port at the baud rate instead.",
    "protocol": "Protocol in use for network connections (TCP, SSH, or UDP). SSH is what makes the processor send user + password as credentials on connect. Not carried by a Serial device.",
    "serial_port": "Serial port in use if using Serial as the com type (e.g. COM1). Only the Serial connection opens a port on the host — a Network or SerialOverEthernet device reaches its hardware by ip_address + net_port, so the field is not offered and the key is not written for those.",
    "service_port": "Port for the response from the device. 0 is automatically assigned by the processor. Not carried by a Serial device — the processor has no service port to open for a COM line.",
    "use_device_mute": "Whether pressing Video Mute also mutes the PICTURE at this display itself — the processor sends the module's AV mute / video mute / shutter command on top of muting the switcher output feeding it. Turn it on for a display that must black out even when it isn't fed from the switcher, or one whose own blanking is cleaner than dropping the signal. Not to be confused with speaker_mute, which is the same idea for the display's SPEAKERS.",
    "user": "Username for the device when using a network connection. Sent as a credential on an SSH or HTTP connection, and pushed into the module's deviceUsername on a plain TCP/UDP one when the driver has that field. Not carried by a Serial device.",
    "password": "Password in use while using a network connection that requires authentication. Paired with 'user' — see that key for how each connection sends it. Not carried by a Serial device.",
    "group_mic_ceiling_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_mic_in_room_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_mic_master_gain": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_mic_master_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_pc_mic_input_gain": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_pc_output_gain": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_pc_output_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_pc_record_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_prog_gain": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_prog_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "group_voice_lift_mute": "Audio group number on the switcher/DSP. Set these in DSP Configurator / PCS, or the third-party device's software (e.g. Yamaha MTX Editor).",
    "processor1": "Device alias for import from the room's Extron json file. These can be used to set the host on serial devices.",
    "processor2": "Device alias for import from the room's Extron json file. These can be used to set the host on serial devices.",
    "spdevice1": "Device alias for import from the room's Extron json file. These can be used to set the host on serial devices.",
    "spdevice2": "Device alias for import from the room's Extron json file. These can be used to set the host on serial devices.",
    "active_debug_server": "Run the processor's debug server, so a debug client can attach to the running room and watch its logs live. Nothing to do with the inactivity timer. The reboot listener (active_reboot_listener) is separate and works with this switched off.",
    "active_event_space": "Put the room on the EVENT inactivity timer — 6 hours before it shuts itself down, against the normal 3. For a room that regularly hosts long sessions with no touch panel activity. The room's Timer button cycles normal / event / disabled and writes the choice back into config.json on the processor; disable_inactivity_timer (25hrs) outranks this flag.",
    "active_notifications": "Send the room's Teams notifications (device offline, system errors) to the teams_webhook URL. The panel can toggle this at runtime and the processor saves the new value back into config.json.",
    "api_proxy_server": "RETIRED. The old API proxy (metrics) server address. Superseded by the METRICS_CONFIG block (uri + bearer), so it is no longer part of the template and is dropped when a legacy config is loaded. Only visible on a file opened with \"Use Original\".",
    "dev_cameras": "How many cameras the room has. Sets how many CAMERADEVICE_n blocks exist (edit them on the Devices tabs) and how many camera controls the panel shows. The processor also uses it to decide whether to route a camera to the capture card at all.",
    "dev_dsps": "How many DSPs the room has. Sets how many DSPDEVICE_n blocks exist. Any count above 0 puts the room in 'DSP system' mode, where volume and mute go to the DSP's audio groups instead of the switcher's.",
    "dev_media_ports": "How many MediaPort USB interfaces the room has. Sets how many MEDIAPORTDEVICE_n blocks exist.",
    "dev_power_controllers": "How many power controllers (APC) the room has. Sets how many POWERDEVICE_n blocks exist. Dropping it to 0 also clears the power1_outlet_* names, since a room with no controller has no outlets to label.",
    "dev_projectors": "How many projectors/displays the room has. Sets how many PROJECTORDEVICE_n blocks exist, how many power buttons the panel shows, and how many output_proj_n outputs the processor routes and video-mutes.",
    "dev_recorders": "How many recorders (AV Bridge and the like) the room has. Sets how many RECORDERDEVICE_n blocks exist.",
    "dev_relay_power": "Whether the room uses processor relay ports for power control (not a device count). Edited under Hardware Options in the Setup Wizard.",
    "dev_screen_control": "How the projection screens are controlled: 'Relay' (processor relay ports), 'Serial' (direct RS-232), 'Serial over Ethernet', or 'Network' (not a device count). Edited under Hardware Options in the Setup Wizard.",
    "dev_screens": "How many projection screens the room has. Sets how many SCREENDEVICE_n blocks exist. How those screens are driven is dev_screen_control (relay ports, serial, or network).",
    "dev_switchers": "How many switchers the room has. Sets how many SWITCHERDEVICE_n blocks exist. Switcher 1 is the main matrix/scaler every route goes through; switchers 2 and 3 are the sub-switchers used for capture-card routing (sub_switch_CC) and Conference mode (conf_display_1 / conf_display_2).",
    "dev_usb_switchers": "How many USB switchers the room has. Sets how many USBDEVICE_n blocks exist — the device that hands the room's USB camera/mic over to the laptop or the room PC.",
    "dev_wireless": "How many wireless presentation devices (ShareLink, VIA) the room has. Sets how many WIRELESSDEVICE_n blocks exist; the wireless source button also needs input_wireless set.",
    "gve_bldg": "Building CODE for GVE (e.g. 'BSS' for Behavioral and Social Science), from buildings.json. The Setup Wizard stores the code here and generates gui_full_room_name from the full building name.",
    "gve_room": "Room number as GVE knows it (e.g. '103'). Paired with gve_bldg it identifies the room to GVE, and the two together name the backup files this app writes (BSS103_old_config.json).",
    "gve_id_processor": "GVE device ID for the processor itself, copied from GVE after the room is created there. Carried in the config as the room's inventory record — device connection statuses are reported under each device block's own gve_id.",
    "gve_id_room_1": "GVE ROOM ID, copied from GVE after the room is created there. This is the one GVE sends room events to: a SystemOn or SystemOff addressed to this ID starts or shuts down the room, so a wrong value means GVE cannot power the room.",
    "gve_id_room_2": "GVE room ID for the second room of a divisible/paired space. Set it to N/A in a single room.",
    "gve_id_tlp_1": "GVE device ID for the touch panel, copied from GVE. The processor reports the panel as Online under this ID at startup and whenever Force Online is pressed, so GVE shows the TLP as connected.",
    "gve_ip": "DNS name or IP of the GVE server the processor connects to (port 5555). Example: gve.csuchico.edu. Every device status, source change and power event the room reports goes here.",
    "input_aud_cam": "Switcher input the audience camera is wired to. Routed to the second capture card (output_cc2) for the far end of a Zoom/Teams call. In a one-camera room, leave the camera you don't have blank — the panel keeps a single 'Camera' routing button and the processor falls back to whichever camera input IS set.",
    "input_blu_ray": "Switcher input the Blu-ray player is wired to. Only reachable when the sources list (gui_inputs) includes BluRay.",
    "input_doc_cam": "Switcher input the document camera is wired to. Only reachable when the sources list (gui_inputs) includes a Doc Cam.",
    "input_dvd": "Switcher input the DVD player is wired to. Only reachable when the sources list (gui_inputs) includes DVD.",
    "input_hdmi": "Switcher input for the room's HDMI connection — the laptop plate or cubby cable. Present on every sources layout.",
    "input_inst_cam": "Switcher input the instructor camera is wired to. Routed to the capture card (output_cc) for a Zoom/Teams call, and sent to LoopOut on switchers that have one (IN1806/IN1808, DTP2 CrossPoint 82). In a one-camera room the audience camera button falls back to this input.",
    "input_pc": "Switcher input the room PC is wired to — the input number to enter when the room has a PC. It is also the room's startup default: at power-on the processor ties it to program audio (output_audio), the ALD feed (output_audio_ald), the confidence monitor (output_monitor_1) and every projector output. Leave it blank in a room with no PC.",
    "input_pc_extended": "Switcher input carrying the PC's SECOND display output (extended desktop). Tied to output_monitor_2 at startup, so the lectern monitor can show a different picture from the projectors. Blank in a room whose PC has one output.",
    "input_usb": "Switcher input for the room's USB-C plate — or the VGA plate in an older room, which is what gui_usb_or_vga selects. The key name stays input_usb either way; only the panel label and this field's label change.",
    "input_wireless": "Switcher input the wireless presentation device (ShareLink, VIA) is wired to. Only reachable when the sources list (gui_inputs) includes Wireless.",
    "output_audio": "Switcher output feeding the room's program audio. Every source selection ties the chosen input here as an Audio-only tie (Audio/Video on a DTP2, which cannot break audio out), so this is the output the volume slider and program mute act on. On a DTP2 CrossPoint 82 the processor forces the audio breakaway to output 2 regardless of this value.",
    "output_cc": "Switcher output feeding the capture card / USB interface used for Zoom and Teams — what the far end sees. The instructor camera routes here by default; on a switcher with a LoopOut (IN1806/IN1808, DTP2 CrossPoint 82) the processor uses that instead of a matrix tie.",
    "output_cc2": "Switcher output feeding a SECOND capture card, used by the audience camera. Setting it is what gives the panel its CC2 routing row — a room without a second capture path leaves it blank.",
    "output_monitor_1": "Switcher output feeding the lectern / confidence monitor. The room PC (input_pc) is tied here at startup as a Video-only tie, so the monitor keeps showing the PC while the projectors follow the source buttons.",
    "output_monitor_2": "Switcher output feeding a second lectern monitor, tied to the PC's extended desktop (input_pc_extended) at startup. Blank in a room with one monitor.",
    "output_proj_1": "Switcher output feeding projector/display 1. Every source selection ties the chosen input here, and video mute is sent to this output. Non-digits are stripped by the processor, so '5B' (a DTP output's B connector) reaches the switcher as output 5. The literal string 'None' skips the mute for a display the switcher does not drive.",
    "output_proj_2": "Switcher output feeding projector/display 2 — see output_proj_1. Only read while dev_projectors is 2 or more.",
    "output_proj_3": "Switcher output feeding projector/display 3 — see output_proj_1. Only read while dev_projectors is 3 or more.",
    "output_proj_4": "Switcher output feeding projector/display 4 — see output_proj_1. Only read while dev_projectors is 4.",
    "conf_display_1": "Input number the conference switcher (SWITCHERDEVICE_3) is set to when 'Display 1' is pressed on the Conference routing page — the codec's first display feed. Read only while gui_routing_mode is Conference.",
    "conf_display_2": "Input number the conference switcher (SWITCHERDEVICE_3) is set to when 'Display 2' is pressed on the Conference routing page — the codec's second display feed. Read only while gui_routing_mode is Conference.",
    "power1_outlet_1": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_2": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_3": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_4": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_5": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_6": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_7": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "power1_outlet_8": "Set the GUI names for the power controller (APC). 23 character limitation.",
    "gui_routing_mode": "How the room's displays are driven. 'Normal': every display follows the selected source. 'Extended': displays 2 and 4 show the PC's extended desktop (input_pc_extended) while 1 and 3 follow the source, and the routing pages switch to their Extended layouts. 'Conference': the room is built around a codec — the Conference routing page appears and drives the conference switcher with conf_display_1 / conf_display_2, and the camera pages change to match.",
    "gui_tab": "Which menu tabs the panel shows down the side of the main page, so a room only carries the controls it has: cameras, microphone, devices, or a combination. Pick the entry matching the room's hardware — the count in each option is how many tabs appear. 'Conference' is the 2-tab camera layout for a codec room and also substitutes the second camera handler, so there is no instructor camera.",
    "gui_routing_available": "Whether the panel offers the routing pages — the video matrix button and the per-destination source picking. 'No' leaves the room on the plain source buttons, which is what most teaching rooms want; 'Yes' suits a room where someone needs to send different sources to different displays.",
    "gui_inputs": "Used in conjunction with gui_tab_type to set the sources in the room for the source and routing pages.",
    "gui_tab_type": "Used in conjunction with gui_inputs to set the sources. (Examples: 3_WL, 4_DOC_USB, 6_DOC_DVD_VGA_WL, etc).",
    "gui_mic_mix": "Specify the Microphone sub page: 'Yes' (Single Mic w/ Ducking), 'No' (Single Mic w/ Mute), 'Ceiling' (Ceiling Mic w/ Voicelift).",
    "gui_preset_name_aud_1": "Button text for the audience camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Left', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_aud_2": "Button text for the audience camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Left', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_aud_3": "Button text for the audience camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Left', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_aud_4": "Button text for the audience camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Left', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_inst_1": "Button text for the instructor camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Lectern', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_inst_2": "Button text for the instructor camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Lectern', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_inst_3": "Button text for the instructor camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Lectern', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_preset_name_inst_4": "Button text for the instructor camera's stored presets 1-4 (the camera holds the actual positions; this only names the buttons). Name them for what the shot is — 'Lectern', 'Wide', 'Whiteboard'. A \\r puts the rest on a second line, which is how a two-word name fits the button.",
    "gui_full_room_name": "Room name printed across the panel's pages, e.g. 'Butte Hall 103'. Free text for people in the room to read — the Setup Wizard fills it in from the building name and room number, unlike gve_bldg/gve_room which are the codes GVE matches on.",
    "mic_max_volume": "Loudest the microphone slider can reach, in dB as the DSP/switcher reads it (processor default 0). With mic_min_volume it defines the range the panel's mic slider maps onto — so 0 to -10 means a full slider is 0 dB and the bottom is -10 dB, not 'off'.",
    "mic_min_volume": "Quietest the microphone slider can reach, in dB (processor default -10). Raise it (e.g. -6) in a room where the bottom of the slider still needs to be audible; lower it for finer control over a wider range.",
    "switch_max_volume": "Loudest the program volume slider can reach, in dB (processor default 0). With switch_min_volume it defines the range the panel's program slider maps onto, whether the level lands on the switcher or the DSP.",
    "switch_min_volume": "Quietest the program volume slider can reach, in dB (processor default -40). This is the floor a user can drag to, not a mute — muting is a separate command.",
    "teams_webhook": "Power Automate webhook URL the room posts its Teams notifications to (device offline, errors). Only used while active_notifications is true; blank it and the room reports nothing.",
    "sub_switch_CC": "Route the capture-card destinations through the SECONDARY switchers instead of the main one: CC1 goes to Switcher 2 and CC2 to Switcher 3, each set by input number rather than a matrix tie. For a room where the capture feeds hang off their own small switcher. Leave it null/false and CC routing stays on switcher 1.",
    "tv_videomute": "On a DTP2 CrossPoint 82 only: when video mute is pressed, DON'T mute switcher output 1 — the display on that output is muted by its own command instead, which keeps the HDBaseT link to the TV alive. Added for Arts 208; leave it 'No' in a room that doesn't need the exception (the other outputs mute normally either way)."
  };
